//! Minimal re-implementation of the sortedcontainers-cpp `SortedSet`
//! interface, backed by `std::collections::BTreeSet`.

use std::collections::BTreeSet;

/// A sorted set of unique elements, mirroring the C++ `SortedSet<T>` API
/// used by the tests: `insert`, `size`, `contains`, `union_with`.
pub struct SortedSet<T: Ord> {
    data: BTreeSet<T>,
}

impl<T: Ord + Clone> SortedSet<T> {
    pub fn new() -> Self {
        SortedSet {
            data: BTreeSet::new(),
        }
    }

    /// Inserts a value; duplicates are ignored.
    pub fn insert(&mut self, value: T) {
        self.data.insert(value);
    }

    /// Number of elements in the set.
    pub fn size(&self) -> usize {
        self.data.len()
    }

    /// Returns true if the value is present.
    pub fn contains(&self, value: &T) -> bool {
        self.data.contains(value)
    }

    /// Returns a new set containing all elements of both sets.
    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T> {
        SortedSet {
            data: self.data.union(&other.data).cloned().collect(),
        }
    }
}

