mod sortedcontainers;

use sortedcontainers::SortedSet;
use std::io::{self, Write};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 6;
    if args.len() > 1 {
        n = args[1].parse::<i32>().unwrap_or(0);
    }

    let mut s1: SortedSet<i32> = SortedSet::new();
    let mut s2: SortedSet<i32> = SortedSet::new();
    for i in 0..n {
        s1.insert(i);
        s2.insert(i * 2);
    }

    let s3 = s1.union_with(&s2);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    writeln!(out, "{}", s1.size()).unwrap();
    writeln!(out, "{}", s2.size()).unwrap();
    writeln!(out, "{}", s3.size()).unwrap();

    for i in 0..n {
        // C++ prints bool as 0/1, each followed by a space.
        write!(out, "{} ", if s3.contains(&i) { 1 } else { 0 }).unwrap();
    }
    writeln!(out).unwrap();
}

