use sortedcontainers::SortedSet;
use std::io::{self, Write};

/// Mirrors C `std::atoi`: skips leading whitespace, accepts an optional
/// sign, then parses digits until a non-digit; yields 0 if no digits.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    if negative {
        value = -value;
    }
    value as i32
}

